{"code":"import json
with open('table.json') as f: table=json.load(f)
syms='ABCDEFGHIJKLMNOPQRSTUVWXY'
# define star(x,y)=P_y(x), where P_y is unique left-permutation class labelled by its A-row output=y.
# For each y, find a pair(c,r) with A c r = y.
rep={}
for c in syms:
    for r in syms:
        y=table['A'+c+r]
        if y not in rep:
            rep[y]=(c,r)
star={}
for y,(c,r) in rep.items():
    for x in syms:
        star[(x,y)] = table[x+c+r]
# test if y from c,r equals c star r
ok=True
bad=None
for c in syms:
    for r in syms:
        y=table['A'+c+r]
        if star[(c,r)] != y:
            ok=False; bad=(c,r,y,star[(c,r)]); break
    if not ok: break
print('g(c,r)=c*r ?', ok, bad)
# test full decomposition l*(c*r)
ok=True
bad=None
for l in syms:
    for c in syms:
        for r in syms:
            v=table[l+c+r]
            w=star[(l, star[(c,r)])]
            if v!=w:
                ok=False; bad=(l,c,r,v,w); break
        if not ok: break
    if not ok: break
print('f(l,c,r)=l*(c*r) ?', ok, bad)
